-- Errata reading for L05: No CKD on the problem list per config/agere/definitions.json chronic_kidney_disease (N18 stages, diabetic kidney disease incl. 'Disorder of kidney due to diabetes mellitus' and E08-E13 .2x, hypertensive CKD I12/I13, CKD labels); latest dated eGFR < 60, worse value of the day.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','labs')), c AS (SELECT patient, json_extract(payload,'$.description') d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM r WHERE stream='conditions'), ckd AS (SELECT DISTINCT patient FROM c WHERE (i LIKE 'N18%' OR lower(d) LIKE '%chronic kidney disease%' OR d LIKE '%CKD%' OR s='46177005' OR lower(d) LIKE '%end-stage renal disease%' OR s='127013003' OR lower(d) LIKE '%kidney due to diabetes%' OR substr(i,1,3) IN ('I12','I13') OR (substr(i,1,3) BETWEEN 'E08' AND 'E13' AND substr(i,5,1)='2'))), g AS (SELECT patient, json_extract(payload,'$.event_date') d, json_extract(payload,'$.value') v FROM r WHERE stream='labs' AND json_extract(payload,'$.name')='eGFR' AND json_extract(payload,'$.event_date') IS NOT NULL AND json_type(payload,'$.value') IN ('integer','real')), last AS (SELECT patient, max(d) d FROM g GROUP BY patient), lastv AS (SELECT g.patient, min(g.v) v FROM g JOIN last l ON l.patient=g.patient AND l.d=g.d GROUP BY g.patient) SELECT patient AS patient_id FROM lastv WHERE v < 60 AND patient NOT IN (SELECT patient FROM ckd) ORDER BY patient;
